<?php
require_once __DIR__.'/../includes/bootstrap.php'; if(customer_logged_in()) redirect('/');
$title='Forgot Password';$errors=[];$sent=false;$lookup=trim((string)($_POST['lookup']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($lookup==='')$errors[]='Enter your registered email or phone number.';if(!$errors){$s=$pdo->prepare('SELECT customer_id,full_name,email,phone FROM customers WHERE status="ACTIVE" AND (LOWER(email)=LOWER(?) OR phone=?) LIMIT 1');$s->execute([$lookup,$lookup]);$c=$s->fetch();if(!$c)$errors[]='No active customer account was found.';else{$otp=(string)random_int(100000,999999);$exp=date('Y-m-d H:i:s',time()+600);$pdo->prepare('DELETE FROM password_reset_otps WHERE customer_id=?')->execute([(int)$c['customer_id']]);$pdo->prepare('INSERT INTO password_reset_otps(customer_id,otp_hash,expires_at) VALUES(?,?,?)')->execute([(int)$c['customer_id'],password_hash($otp,PASSWORD_DEFAULT),$exp]);if(send_customer_otp_html($c['email'],$otp)){$_SESSION['reset_customer_id']=(int)$c['customer_id'];$_SESSION['reset_lookup']=$lookup;$_SESSION['reset_expires']=$exp;$_SESSION['reset_last_sent']=time();$sent=true;}else{$pdo->prepare('DELETE FROM password_reset_otps WHERE customer_id=?')->execute([(int)$c['customer_id']]);$errors[]='We found your account but could not send the email. Please try again later.';}}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/assets/style.css?v=22"></head><body class="auth-body"><div class="auth-wrap"><a class="brand auth-brand" href="/"><img src="/assets/shadril-logo.png" style="width:44px;height:44px;object-fit:contain;border-radius:10px" alt=""> Shadril Shopping Store</a><div class="auth-page-back"><?=back_button('Previous page')?></div><div class="auth-card auth-special"><div class="auth-icon">🔐</div><div class="auth-copy"><span class="eyebrow">SECURE ACCOUNT RECOVERY</span><h1>Forgot your password?</h1><p>Enter your registered email or phone. The verification OTP is always sent to your registered email address.</p></div><?php if($errors): ?><div class="errors"><?=e($errors[0])?></div><?php endif; ?><?php if($sent): ?><div class="flash success">OTP sent successfully to your registered email.</div><a class="btn primary full" href="/auth/verify-otp.php">Continue to OTP verification</a><?php else: ?><form method="post" class="form"><?=csrf_field()?><label>Registered email or phone<input name="lookup" required value="<?=e($lookup)?>" autocomplete="username"></label><button class="btn primary full">Send OTP to registered email</button></form><?php endif; ?><p class="auth-links"><a href="/auth/customer-login.php">← Back to sign in</a></p></div></div></body></html>